<section class="panel stack" id="ask-voice-pane" hidden aria-label="Record-backed job conversation">
<style>#ask-voice-controls{display:flex;flex-wrap:wrap;gap:8px}#ask-voice-controls p{width:100%;margin:4px 0}#ask-job-detail{min-width:0;overflow-wrap:anywhere}#ask-job-detail h3{font:24px Georgia,serif}#ask-job-detail dl{display:grid;grid-template-columns:1fr 1fr;gap:12px}#ask-job-detail dt{font-size:11px;color:var(--muted)}#ask-job-detail dd{margin:5px 0;white-space:pre-wrap}#ask-job-detail a{display:inline-flex;align-items:center;min-height:44px}#ask-message-preview{width:min(600px,calc(100vw - 32px));max-height:calc(100dvh - 32px);overflow:auto;border:1px solid var(--line);border-radius:12px;padding:25px;color:var(--ink)}#ask-message-preview::backdrop{background:#142a24b8}#ask-message-preview pre{font:14px/1.7 inherit;white-space:pre-wrap;overflow-wrap:anywhere}#ask-message-preview button{min-height:44px}@media(max-width:650px){#ask-job-detail dl{grid-template-columns:1fr}.ask-grid{grid-template-columns:minmax(0,1fr)}}</style>
<div><div class="eyebrow">Ask Everbranch</div><h3>Talk about your current work</h3></div>
<div id="ask-voice-controls"></div><div id="ask-job-detail" aria-live="polite"><p class="caption">Ask for a job by title. Only current permitted records can appear here.</p></div>
<div id="ask-message-preview-actions" class="actions" hidden><button class="button" type="button" data-ask-preview="email">Preview email</button><button class="button" type="button" data-ask-preview="text">Preview text</button></div>
<p class="caption">These message previews do not select a recipient, connect an account or send anything. Actual email uses the separately authorized mailbox flow.</p>
</section>
<dialog id="ask-message-preview" aria-labelledby="ask-message-preview-title"><span class="badge">Preview · not sent</span><h2 id="ask-message-preview-title">Job update preview</h2><p class="caption">Recipient not selected. Review current facts and obtain required authorization before any real message.</p><pre id="ask-message-preview-body"></pre><button class="button" type="button" id="ask-message-preview-close">Close preview</button></dialog>
